import logging
from taf.collectors.core.util.string_formatting import partial_format
from taf.converters.base import NToNConverterObject

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class TsharkConverter(NToNConverterObject):
    """
    Convert files using tshark command.
    """

    def __init__(self,
                 name='default',
                 options=None,
                 tshark_path=None,
                 binary=False,
                 **kwargs):
        if binary:
            self._binary = "-w"
        else:
            self._binary = ">"
        self._tshark_path = tshark_path or "tshark"
        self._options = " {options}".format(options=options) if options else ""
        self._sudo_prefix = ''
        self._tshark_command_list = None
        self._pid_file_folder = partial_format(
            '/tmp/tshark_converter_{name}'.format(name=name),
            options=self._options)
        command_template = partial_format(
            '''bash -c "mkdir -p '{pid_file_folder}' ; '''
            '''touch '{pid_file_folder}'/$$ ; '''
            '''exec '{tshark_path}' -r '{input_file}'{options} {binary} '{output_file}'"''',
            tshark_path=self._tshark_path,
            options=self._options,
            binary=self._binary,
            pid_file_folder=self._pid_file_folder)
        super(TsharkConverter, self).__init__(command_template=command_template, **kwargs)

    def _setup(self):
        self._sudo_prefix = self._executor.sudo_prefix()
        self._check_pid_list_and_terminate_process()

    def _teardown(self):
        self._check_pid_list_and_terminate_process()

    def _check_pid_list_and_terminate_process(self):
        kill_command = ("[ -d '{pid_file_folder}' ] || exit 0 ; "
                        "cd '{pid_file_folder}'; for pid in * ; do kill $pid 2>&1; done; :").format(
            pid_file_folder=self._pid_file_folder)
        self._executor.execute(kill_command.encode('utf-8'))

        remove_command = "rm -rf '{pid_file_folder}'".format(
            pid_file_folder=self._pid_file_folder)
        self._executor.execute(remove_command.encode('utf-8'))
